#!/usr/bin/env python3
"""Compile common/server collision geometry from the same cuboids used by machine models."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
shapes=json.loads((ROOT/'tools/machine_shapes.json').read_text())
arrays='\n'.join('    private static final double[][] '+key.upper()+' = {\n'+',\n'.join('        {'+', '.join(str(n) for n in box)+'}' for box in boxes)+'\n    };' for key,boxes in shapes.items())
source='''package dev.emily.economy;

// Generated by tools/generate_machine_shapes.py. Edit source model geometry, then regenerate.
import net.minecraft.core.Direction;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

public final class MachineShapes {
'''+arrays+'''
    private static final VoxelShape[] ATM_PARTS = build(ATM);
    private static final VoxelShape[] TELLER_PARTS = build(BANK_TELLER_STATION);
    private static final VoxelShape[] STOCK_PARTS = build(STOCK_TRADING_COMPUTER);
    private MachineShapes() {}
    public static VoxelShape atm(BlockState state) { return forState(ATM_PARTS,state); }
    public static VoxelShape workstation(boolean teller,BlockState state) {
        return forState(teller ? TELLER_PARTS : STOCK_PARTS,state);
    }
    private static VoxelShape forState(VoxelShape[] parts,BlockState state) {
        return parts[index(state.getValue(WideMachineBlock.FACING),state.getValue(WideMachineBlock.RIGHT),
            state.getValue(WideMachineBlock.HALF)==DoubleBlockHalf.UPPER)];
    }
    static VoxelShape part(String kind,Direction facing,boolean right,boolean upper) {
        VoxelShape[] shapes=switch(kind) {
            case "atm" -> ATM_PARTS;
            case "bank_teller_station" -> TELLER_PARTS;
            case "stock_trading_computer" -> STOCK_PARTS;
            default -> throw new IllegalArgumentException(kind);
        };
        return shapes[index(facing,right,upper)];
    }
    private static int index(Direction facing,boolean right,boolean upper) {
        if(facing.getAxis().isVertical()) throw new IllegalArgumentException("Horizontal facing required");
        return facing.get2DDataValue()*4+(right ? 1 : 0)+(upper ? 2 : 0);
    }
    private static VoxelShape[] build(double[][] boxes) {
        VoxelShape[] result=new VoxelShape[16];
        for(Direction facing:Direction.Plane.HORIZONTAL) for(int side=0;side<2;side++) for(int half=0;half<2;half++) {
            VoxelShape shape=Shapes.empty();
            for(double[] box:boxes) {
                double x=Math.max(box[0],side*16),X=Math.min(box[3],side*16+16);
                double y=Math.max(box[1],half*16),Y=Math.min(box[4],half*16+16);
                if(x>=X || y>=Y) continue;
                x-=side*16;X-=side*16;y-=half*16;Y-=half*16;
                shape=Shapes.or(shape,rotate(x,y,box[2],X,Y,box[5],facing));
            }
            result[index(facing,side==1,half==1)]=shape.optimize();
        }
        return result;
    }
    private static VoxelShape rotate(double x,double y,double z,double X,double Y,double Z,Direction facing) {
        return switch(facing) {
            case EAST -> Shapes.box((16-Z)/16,y/16,x/16,(16-z)/16,Y/16,X/16);
            case SOUTH -> Shapes.box((16-X)/16,y/16,(16-Z)/16,(16-x)/16,Y/16,(16-z)/16);
            case WEST -> Shapes.box(z/16,y/16,(16-X)/16,Z/16,Y/16,(16-x)/16);
            default -> Shapes.box(x/16,y/16,z/16,X/16,Y/16,Z/16);
        };
    }
}
'''
out=ROOT/'src/generated/java/dev/emily/economy/MachineShapes.java';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(source)
print('Generated common collision geometry:',out)
